import { ArrowLeft, BookOpen, Shuffle, Plus, Type, Users, Swords } from "lucide-react";
import { ImportRecord, PkMatchMode } from "@/types/pk";

interface Props {
  matchMode: PkMatchMode;
  sourceType: "import" | "random";
  questionCount: number;
  timePerQuestion: number;
  spellingRatio: number;
  selectedImportId: string;
  importRecords: ImportRecord[];
  myWordCount: number;
  onMatchModeChange: (m: PkMatchMode) => void;
  onSourceTypeChange: (t: "import" | "random") => void;
  onQuestionCountChange: (n: number) => void;
  onTimePerQuestionChange: (n: number) => void;
  onSpellingRatioChange: (n: number) => void;
  onSelectedImportIdChange: (id: string) => void;
  onBack: () => void;
  onCreate: () => void;
}

export function PkCreateView({
  matchMode,
  sourceType,
  questionCount,
  timePerQuestion,
  spellingRatio,
  selectedImportId,
  importRecords,
  myWordCount,
  onMatchModeChange,
  onSourceTypeChange,
  onQuestionCountChange,
  onTimePerQuestionChange,
  onSpellingRatioChange,
  onSelectedImportIdChange,
  onBack,
  onCreate,
}: Props) {
  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 flex flex-col overflow-hidden">
      <div className="flex items-center gap-3 p-4">
        <button
          onClick={onBack}
          className="w-10 h-10 rounded-full bg-slate-800/60 border border-slate-600/50 flex items-center justify-center text-white hover:scale-105 transition-transform"
        >
          <ArrowLeft size={20} />
        </button>
        <h1 className="text-xl font-bold text-slate-100">创建房间</h1>
      </div>

      <div className="flex-1 min-h-0 p-6 overflow-y-auto">
        <div className="w-full max-w-sm mx-auto flex flex-col gap-6">
          <div className="space-y-3">
            <p className="text-slate-300 font-medium">对战模式</p>
            <div className="grid grid-cols-2 gap-3">
              <button
                onClick={() => onMatchModeChange("same")}
                className={`p-4 rounded-xl border-2 transition-all text-left ${
                  matchMode === "same"
                    ? "border-emerald-400 bg-emerald-500/20"
                    : "border-slate-700 bg-slate-800/40"
                }`}
              >
                <Users size={24} className={matchMode === "same" ? "text-emerald-300" : "text-slate-500"} />
                <p className={`text-sm mt-2 font-medium ${matchMode === "same" ? "text-emerald-200" : "text-slate-400"}`}>
                  同词本对战
                </p>
                <p className="text-xs text-slate-600 mt-1 leading-relaxed">
                  双方使用同一套题目
                </p>
              </button>
              <button
                onClick={() => onMatchModeChange("different")}
                className={`p-4 rounded-xl border-2 transition-all text-left ${
                  matchMode === "different"
                    ? "border-violet-400 bg-violet-500/20"
                    : "border-slate-700 bg-slate-800/40"
                }`}
              >
                <Swords size={24} className={matchMode === "different" ? "text-violet-300" : "text-slate-500"} />
                <p className={`text-sm mt-2 font-medium ${matchMode === "different" ? "text-violet-200" : "text-slate-400"}`}>
                  异词本对战
                </p>
                <p className="text-xs text-slate-600 mt-1 leading-relaxed">
                  各自使用自己的词库
                </p>
              </button>
            </div>
          </div>

          <div className="space-y-3">
            <p className="text-slate-300 font-medium">题目来源</p>
            <div className="grid grid-cols-2 gap-3">
              <button
                onClick={() => onSourceTypeChange("random")}
                className={`p-4 rounded-xl border-2 transition-all ${
                  sourceType === "random"
                    ? "border-emerald-400 bg-emerald-500/20"
                    : "border-slate-700 bg-slate-800/40"
                }`}
              >
                <Shuffle size={24} className={sourceType === "random" ? "text-emerald-300" : "text-slate-500"} />
                <p className={`text-sm mt-2 ${sourceType === "random" ? "text-emerald-200" : "text-slate-400"}`}>
                  我的单词本
                </p>
                <p className="text-xs text-slate-600 mt-1">{myWordCount} 词</p>
              </button>
              <button
                onClick={() => onSourceTypeChange("import")}
                className={`p-4 rounded-xl border-2 transition-all ${
                  sourceType === "import"
                    ? "border-emerald-400 bg-emerald-500/20"
                    : "border-slate-700 bg-slate-800/40"
                }`}
              >
                <BookOpen size={24} className={sourceType === "import" ? "text-emerald-300" : "text-slate-500"} />
                <p className={`text-sm mt-2 ${sourceType === "import" ? "text-emerald-200" : "text-slate-400"}`}>
                  导入记录
                </p>
                <p className="text-xs text-slate-600 mt-1">{importRecords.length} 份</p>
              </button>
            </div>
          </div>

          {sourceType === "import" && (
            <div className="space-y-2">
              <p className="text-slate-300 font-medium">选择导入记录</p>
              {importRecords.length === 0 ? (
                <p className="text-slate-500 text-sm bg-slate-800/40 rounded-xl p-4 text-center">
                  暂无导入记录，先去导入一些单词吧
                </p>
              ) : (
                <div className="space-y-2">
                  {importRecords.map((r) => (
                    <button
                      key={r.id}
                      onClick={() => onSelectedImportIdChange(r.id)}
                      className={`w-full p-3 rounded-xl border text-left transition-all ${
                        selectedImportId === r.id
                          ? "border-emerald-400 bg-emerald-500/20"
                          : "border-slate-700 bg-slate-800/40"
                      }`}
                    >
                      <p className={selectedImportId === r.id ? "text-emerald-200" : "text-slate-200"}>
                        {r.title}
                      </p>
                      <div className="flex items-center gap-3 text-xs mt-1">
                        <span className="text-slate-500">{r.wordCount} 词</span>
                        <span className="text-slate-600">·</span>
                        <span className="text-slate-500">
                          {new Date(r.createdAt).toLocaleDateString("zh-CN")}
                        </span>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="space-y-2">
            <p className="text-slate-300 font-medium">题量</p>
            <div className="grid grid-cols-4 gap-2">
              {[5, 10, 15, 20].map((n) => (
                <button
                  key={n}
                  onClick={() => onQuestionCountChange(n)}
                  className={`py-2.5 rounded-lg font-bold transition-all ${
                    questionCount === n
                      ? "bg-emerald-500 text-white"
                      : "bg-slate-800/40 text-slate-400"
                  }`}
                >
                  {n}题
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <p className="text-slate-300 font-medium">每题时间</p>
            <div className="grid grid-cols-4 gap-2">
              {[10, 15, 20, 30].map((n) => (
                <button
                  key={n}
                  onClick={() => onTimePerQuestionChange(n)}
                  className={`py-2.5 rounded-lg font-bold transition-all ${
                    timePerQuestion === n
                      ? "bg-cyan-500 text-white"
                      : "bg-slate-800/40 text-slate-400"
                  }`}
                >
                  {n}秒
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <p className="text-slate-300 font-medium flex items-center gap-2">
              <Type size={16} />
              拼写题占比
            </p>
            <div className="grid grid-cols-4 gap-2">
              {[0, 0.3, 0.5, 1].map((r) => (
                <button
                  key={r}
                  onClick={() => onSpellingRatioChange(r)}
                  className={`py-2.5 rounded-lg font-bold transition-all text-sm ${
                    spellingRatio === r
                      ? "bg-violet-500 text-white"
                      : "bg-slate-800/40 text-slate-400"
                  }`}
                >
                  {r === 0 ? "无" : `${Math.round(r * 100)}%`}
                </button>
              ))}
            </div>
            <p className="text-slate-500 text-xs">
              拼写题需根据中文释义输入单词拼写，输入方式遵循您的游戏设置
            </p>
          </div>

          <button
            onClick={onCreate}
            disabled={sourceType === "import" && !selectedImportId}
            className="w-full py-4 bg-gradient-to-r from-emerald-500 to-teal-500 text-white font-bold text-lg rounded-2xl shadow-lg hover:scale-105 active:scale-95 transition-all disabled:opacity-40 disabled:hover:scale-100 flex items-center justify-center gap-2"
          >
            <Plus size={22} />
            创建房间
          </button>

          <p className="text-slate-500 text-xs text-center">
            {matchMode === "same"
              ? "题目将从你选择的词库中抽取，对手加入后使用同一套题目"
              : "对手需要选择自己的词库迎战，双方各自作答，答对更多者获胜"}
          </p>
        </div>
      </div>
    </div>
  );
}
