import { useState, useEffect, useCallback } from "react";
import { X, Sprout, User, Trophy } from "lucide-react";
import { RankingPlayer, FarmSnapshot } from "@/utils/rankingApi";
import { queueSteal } from "@/utils/stealSync";
import { SeedType, SEED_CONFIGS, PLOT_UNLOCK_COSTS } from "@/types/game";
import { useFarmStore } from "@/store/useFarmStore";
import { getUserInfo } from "@/utils/userInfo";

interface PlayerFarmModalProps {
  open: boolean;
  onClose: () => void;
  player: RankingPlayer | null;
}

const STAGE_CONFIG: Record<string, { label: string; icon: string }> = {
  seedling: { label: "幼苗", icon: "🌱" },
  flowering: { label: "开花", icon: "🌸" },
  fruiting: { label: "结果", icon: "🍎" },
};

function getGrowthStage(plantedAt: number, growthHours: number): string {
  const elapsedMs = Date.now() - plantedAt;
  const totalMs = growthHours * 60 * 60 * 1000;
  const progress = Math.min(1, elapsedMs / totalMs);
  if (progress < 1 / 3) return "seedling";
  if (progress < 2 / 3) return "flowering";
  return "fruiting";
}

function getStageProgress(plantedAt: number, growthHours: number): number {
  const elapsedMs = Date.now() - plantedAt;
  const totalMs = growthHours * 60 * 60 * 1000;
  return Math.min(1, elapsedMs / totalMs);
}

function getTimeRemaining(plantedAt: number, growthHours: number): { hours: number; minutes: number } {
  const elapsedMs = Date.now() - plantedAt;
  const totalMs = growthHours * 60 * 60 * 1000;
  const remainingMs = Math.max(0, totalMs - elapsedMs);
  const totalMinutes = Math.ceil(remainingMs / (1000 * 60));
  return {
    hours: Math.floor(totalMinutes / 60),
    minutes: totalMinutes % 60,
  };
}

function isReadyToHarvest(plantedAt: number, growthHours: number): boolean {
  return getStageProgress(plantedAt, growthHours) >= 1;
}

// 成熟后超过多久才能被偷（毫秒）- 1小时
const STEALABLE_AFTER_MS = 60 * 60 * 1000;

function isStealable(plantedAt: number, growthHours: number): boolean {
  const now = Date.now();
  const totalMs = growthHours * 3600000;
  const elapsedMs = now - plantedAt;
  if (elapsedMs < totalMs) return false;
  return elapsedMs - totalMs >= STEALABLE_AFTER_MS;
}

interface SelectedCrop {
  cropId: string;
  seedType: SeedType;
  plotIndex: number;
  ready: boolean;
  stealable: boolean;
}

export default function PlayerFarmModal({ open, onClose, player }: PlayerFarmModalProps) {
  const [, setTick] = useState(0);
  const [stealMsg, setStealMsg] = useState<{ text: string; type: "success" | "error" } | null>(null);
  const [selectedCrop, setSelectedCrop] = useState<SelectedCrop | null>(null);
  const [localFarmData, setLocalFarmData] = useState<FarmSnapshot | null>(null);

  const remainingSteals = useFarmStore((s) => s.getRemainingSteals());
  const hasStolenCrop = useFarmStore((s) => s.hasStolenCrop);
  const stealFruitLocal = useFarmStore((s) => s.stealFruit);

  const myInfo = getUserInfo();
  const myUuid = myInfo.uuid;
  const myNickname = myInfo.nickname;
  const isSelf = player ? player.uuid === myUuid : false;

  // 当打开或玩家变化时，同步本地 farmData
  useEffect(() => {
    if (!open || !player) {
      setLocalFarmData(null);
      return;
    }
    setLocalFarmData(player.farmData || null);
  }, [open, player]);

  useEffect(() => {
    if (!open) return;
    setSelectedCrop(null);
    const interval = setInterval(() => setTick((t) => t + 1), 60000);
    return () => clearInterval(interval);
  }, [open, player?.uuid]);

  const handleSteal = useCallback(() => {
    if (!selectedCrop || !player) return;
    const farmData: FarmSnapshot | undefined = localFarmData || player.farmData;
    if (!farmData) return;

    // 更新本地偷菜次数 & 仓库
    stealFruitLocal(selectedCrop.seedType, player.uuid, selectedCrop.cropId);

    // 更新本地显示的农场数据（移除被偷的作物，加被偷记录）
    const now = Date.now();
    const newCrops = farmData.plantedCrops.filter((c) => c.id !== selectedCrop.cropId);
    const newRecord = {
      plotIndex: selectedCrop.plotIndex,
      seedType: selectedCrop.seedType as string,
      stolenAt: now,
      thiefUuid: myUuid,
      thiefNickname: myNickname,
    };
    const oldRecords = farmData.stolenRecords || [];
    const newRecords = [...oldRecords, newRecord].slice(-30);
    setLocalFarmData({
      ...farmData,
      plantedCrops: newCrops,
      stolenRecords: newRecords,
      snapshotAt: now,
    });

    // 入队异步同步（30秒抖动 + 关页兜底）
    queueSteal(player.uuid, selectedCrop.cropId, selectedCrop.seedType);

    setStealMsg({ text: "偷菜成功", type: "success" });
    setSelectedCrop(null);
    setTimeout(() => setStealMsg(null), 2000);
  }, [selectedCrop, player, localFarmData, myUuid, myNickname, stealFruitLocal]);

  if (!open || !player) return null;

  const farmData: FarmSnapshot | undefined = localFarmData || player.farmData;
  const hasFarmData = farmData && farmData.snapshotAt > 0;

  const renderPlot = (index: number) => {
    if (!farmData) {
      return (
        <div
          key={index}
          className="aspect-square rounded-2xl border-2 border-dashed border-slate-700/30 bg-slate-800/20 flex items-center justify-center opacity-50"
        >
          <span className="text-slate-600 text-xs">—</span>
        </div>
      );
    }

    const isLocked = index >= farmData.openedPlots;
    const crop = farmData.plantedCrops.find((c) => c.plotIndex === index);
    const stolen = farmData.stolenRecords?.find((r) => r.plotIndex === index && !crop);

    if (isLocked) {
      const cost = PLOT_UNLOCK_COSTS[index];
      const isNext = index === farmData.openedPlots;
      return (
        <div
          key={index}
          className={`aspect-square rounded-2xl border-2 flex flex-col items-center justify-center gap-1 ${
            isNext
              ? "bg-slate-800/30 border-slate-600/50"
              : "bg-slate-900/50 border-slate-700/30 opacity-40"
          }`}
        >
          <span className="text-2xl opacity-60">🔒</span>
          {isNext && cost !== undefined && (
            <span className="text-[10px] text-slate-500">☀️ {cost}</span>
          )}
        </div>
      );
    }

    // 被偷了的地块（没有作物了但有被偷记录）
    if (!crop && stolen) {
      const cfg = SEED_CONFIGS[stolen.seedType as SeedType];
      return (
        <div
          key={index}
          className="aspect-square rounded-2xl border-2 border-dashed border-slate-600/40 bg-slate-800/30 flex flex-col items-center justify-center opacity-70"
        >
          <span className="text-3xl grayscale opacity-50">🥀</span>
          <span className="text-[9px] text-slate-500">{cfg?.name || "作物"}被偷</span>
        </div>
      );
    }

    if (crop) {
      const seedType = crop.seedType as SeedType;
      const config = SEED_CONFIGS[seedType];
      if (!config) {
        return (
          <div
            key={index}
            className="aspect-square rounded-2xl border-2 border-slate-700/30 bg-slate-800/30 flex items-center justify-center"
          >
            <span className="text-slate-500">❓</span>
          </div>
        );
      }
      const ready = isReadyToHarvest(crop.plantedAt, config.growthHours);
      const stealable = isStealable(crop.plantedAt, config.growthHours);
      const stage = getGrowthStage(crop.plantedAt, config.growthHours);
      const progress = getStageProgress(crop.plantedAt, config.growthHours);
      const remaining = getTimeRemaining(crop.plantedAt, config.growthHours);
      const alreadyStolen = !isSelf && hasStolenCrop(player.uuid, crop.id);
      const isSelected = selectedCrop?.cropId === crop.id;

      const baseClass = `relative aspect-square rounded-2xl border-2 flex flex-col items-center justify-center gap-1 transition-all ${
        isSelected
          ? "ring-2 ring-violet-400 ring-offset-2 ring-offset-slate-900 scale-[1.02]"
          : ""
      }`;

      if (ready) {
        if (alreadyStolen) {
          return (
            <button
              key={index}
              onClick={() => setSelectedCrop({ cropId: crop.id, seedType, plotIndex: index, ready, stealable })}
              className={`${baseClass} border-slate-600/30 bg-slate-800/30 opacity-50`}
            >
              <span className="text-3xl grayscale">{config.fruitEmoji}</span>
              <span className="text-[10px] text-slate-500">{config.name}</span>
              <div className="absolute inset-0 rounded-2xl flex items-center justify-center">
                <span className="text-slate-400 text-xs font-bold">已偷</span>
              </div>
            </button>
          );
        }
        // 成熟但还没到可偷时间
        if (!stealable) {
          const overripeMs = (Date.now() - crop.plantedAt) - config.growthHours * 3600000;
          const waitMs = STEALABLE_AFTER_MS - overripeMs;
          const waitMin = Math.ceil(waitMs / 60000);
          return (
            <button
              key={index}
              onClick={() => setSelectedCrop({ cropId: crop.id, seedType, plotIndex: index, ready, stealable })}
              className={`${baseClass} border-emerald-400/40 bg-emerald-500/10 hover:bg-emerald-500/20`}
            >
              <span className="text-3xl">{config.fruitEmoji}</span>
              <span className="text-[10px] text-slate-300">{config.name}</span>
              <span className="absolute top-1 right-1 text-[9px] text-emerald-400 bg-emerald-900/50 rounded px-1">
                {waitMin}分可偷
              </span>
            </button>
          );
        }
        // 可偷
        return (
          <button
            key={index}
            onClick={() => setSelectedCrop({ cropId: crop.id, seedType, plotIndex: index, ready, stealable })}
            className={`${baseClass} border-emerald-400/50 bg-emerald-500/20 hover:bg-emerald-500/30 hover:border-emerald-400`}
          >
            <span className="text-3xl">{config.fruitEmoji}</span>
            <span className="text-[10px] text-slate-200">{config.name}</span>
            <div className="absolute -top-1 -right-1 w-5 h-5 bg-emerald-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-emerald-300">✓</div>
          </button>
        );
      }

      return (
        <button
          key={index}
          onClick={() => setSelectedCrop({ cropId: crop.id, seedType, plotIndex: index, ready, stealable: false })}
          className={`${baseClass} border-amber-600/30 bg-amber-900/30 hover:bg-amber-900/40`}
        >
          <span className="text-3xl">{STAGE_CONFIG[stage].icon}</span>
          <span className="text-[10px] text-slate-300">{config.name}</span>
          <div className="absolute bottom-1.5 left-1.5 right-1.5">
            <div className="w-full h-1 bg-slate-700/50 rounded-full overflow-hidden">
              <div
                className="h-full bg-amber-400"
                style={{ width: `${Math.round(progress * 100)}%` }}
              />
            </div>
          </div>
          <span className="absolute top-1 right-1 text-[9px] text-slate-400 bg-slate-800/70 rounded px-1">
            {remaining.hours > 0 ? `${remaining.hours}h${remaining.minutes}m` : `${remaining.minutes}m`}
          </span>
        </button>
      );
    }

    return (
      <div
        key={index}
        className="aspect-square rounded-2xl border-2 border-dashed border-slate-600/30 bg-slate-800/20 flex flex-col items-center justify-center"
      >
        <span className="text-2xl opacity-30">➕</span>
        <span className="text-[10px] text-slate-600">空地</span>
      </div>
    );
  };

  const renderToolbar = () => {
    if (!selectedCrop) return null;
    const config = SEED_CONFIGS[selectedCrop.seedType];

    const canSteal = !isSelf && selectedCrop.stealable && !hasStolenCrop(player.uuid, selectedCrop.cropId) && remainingSteals > 0;

    return (
      <div className="shrink-0 mt-3 p-3 rounded-xl bg-slate-800/50 border border-slate-700/30">
        <div className="flex items-center gap-2 mb-2">
          <span className="text-xl">{config?.fruitEmoji || "🌱"}</span>
          <div className="flex-1 min-w-0">
            <p className="text-slate-200 text-sm font-medium truncate">
              {config?.name || "未知作物"}
              {selectedCrop.ready && <span className="text-emerald-400 ml-1">· 已成熟</span>}
              {!selectedCrop.ready && <span className="text-amber-400 ml-1">· 生长中</span>}
            </p>
            {isSelf && <p className="text-slate-500 text-xs">这是你自己的农场</p>}
          </div>
        </div>
        <div className="flex gap-2">
          {!isSelf && selectedCrop.stealable && (
            <button
              onClick={handleSteal}
              disabled={!canSteal}
              className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all flex items-center justify-center gap-2 ${
                canSteal
                  ? "bg-emerald-500 hover:bg-emerald-400 text-white active:scale-[0.98]"
                  : "bg-slate-700/50 text-slate-500 cursor-not-allowed"
              }`}
            >
              {hasStolenCrop(player.uuid, selectedCrop.cropId)
                ? "今天已偷过"
                : remainingSteals <= 0
                  ? "今日次数用完"
                  : `摘取（剩 ${remainingSteals}）`}
            </button>
          )}
          {!isSelf && selectedCrop.ready && !selectedCrop.stealable && (
            <div className="flex-1 py-2 text-center text-slate-500 text-sm">
              刚成熟，再等等才能偷
            </div>
          )}
          {!isSelf && !selectedCrop.ready && (
            <div className="flex-1 py-2 text-center text-slate-500 text-sm">
              还未成熟，无法摘取
            </div>
          )}
          {isSelf && (
            <div className="flex-1 py-2 text-center text-slate-500 text-sm">
              自己的作物不可偷取
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderContent = () => {
    if (!hasFarmData) {
      return (
        <div className="text-center py-12 text-slate-500">
          <Sprout size={32} className="mx-auto mb-3 opacity-40" />
          <p>该玩家暂未上传农场数据</p>
          <p className="text-xs mt-1 text-slate-600">刷新最高关卡时会自动同步农场</p>
        </div>
      );
    }

    return (
      <div className="space-y-4">
        <p className="text-slate-400 text-xs">
          种植区 ({farmData!.openedPlots}/{farmData!.totalPlots} 已开垦)
        </p>
        <div className="grid grid-cols-3 gap-1.5 max-w-[280px] mx-auto">
          {Array.from({ length: farmData!.totalPlots }).map((_, i) => renderPlot(i))}
        </div>
        {farmData!.snapshotAt && (
          <p className="text-slate-600 text-[10px] text-center">
            数据更新于 {new Date(farmData!.snapshotAt).toLocaleString("zh-CN")}
          </p>
        )}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-emerald-500/30 rounded-3xl p-6 sm:p-8 max-w-sm w-full shadow-2xl max-h-[85vh] flex flex-col">
        <div className="absolute -top-6 left-1/2 -translate-x-1/2">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center shadow-lg shadow-emerald-500/50">
            <Sprout className="text-white" size={24} />
          </div>
        </div>

        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
        >
          <X size={20} />
        </button>

        <div className="mb-4 mt-4 space-y-2">
          <div className="flex items-center gap-3 p-3 rounded-xl bg-slate-800/30 border border-slate-700/30">
            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center shrink-0">
              <User size={18} className="text-white" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-slate-200 font-semibold truncate">
                {player.nickname} 的农场
                {isSelf && <span className="text-violet-400 text-xs ml-1">(我)</span>}
              </p>
              <p className="text-slate-400 text-xs flex items-center gap-1">
                <Trophy size={12} className="text-amber-400" />
                最高关卡 {player.bestLevel}
              </p>
            </div>
          </div>
          {!isSelf && (
            <div className="flex items-center justify-between px-3 py-2 rounded-xl bg-amber-500/10 border border-amber-400/20">
              <span className="text-amber-300/80 text-xs">今日剩余偷菜次数</span>
              <span className="text-amber-300 font-bold text-sm">{remainingSteals}/5</span>
            </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto pr-1 -mr-1">
          {renderContent()}
        </div>

        {renderToolbar()}

        {stealMsg && (
          <div className={`absolute left-1/2 -translate-x-1/2 top-4 px-4 py-2 rounded-xl text-sm font-medium shadow-lg z-10 ${
            stealMsg.type === "success"
              ? "bg-emerald-500/90 text-white"
              : "bg-rose-500/90 text-white"
          }`}>
            {stealMsg.text}
          </div>
        )}
      </div>
    </div>
  );
}
